import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.BG8d4IEm.js";const b=JSON.parse('{"title":"BNF 范式","description":"","frontmatter":{"tags":["计算机基础"]},"headers":[],"relativePath":"posts/2016-08-22-bnf.md","filePath":"posts/2016-08-22-bnf.md"}'),l={name:"posts/2016-08-22-bnf.md"};function o(d,e,s,c,i,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="bnf-范式" tabindex="-1">BNF 范式 <a class="header-anchor" href="#bnf-范式" aria-label="Permalink to &quot;BNF 范式&quot;">​</a></h1><h2 id="什么是-bnf-范式" tabindex="-1">什么是 BNF 范式 <a class="header-anchor" href="#什么是-bnf-范式" aria-label="Permalink to &quot;什么是 BNF 范式&quot;">​</a></h2><p>BNF(Backus-Naur Form) 巴克斯范式用来描述语法规则的语法。 使用场景如下:</p><ol><li><a href="https://cs.wmich.edu/~gupta/teaching/cs4850/sumII06/The%20syntax%20of%20C%20in%20Backus-Naur%20form.htm" target="_blank" rel="noreferrer">C 语言的 BNF 描述</a></li><li><a href="https://www.w3.org/TR/CSS21/grammar.html" target="_blank" rel="noreferrer">CSS 语法规则描述</a></li><li>linux 指令使用的描述,使用 <code>man &lt;command_name&gt;</code> 查看指令时看到的 <code>SYNOPSIS</code> 极为 bnf 的语法描述。</li></ol><h2 id="为什么需要学习-bnf" tabindex="-1">为什么需要学习 bnf <a class="header-anchor" href="#为什么需要学习-bnf" aria-label="Permalink to &quot;为什么需要学习 bnf&quot;">​</a></h2><p>理解 bnf 除了能够更好的读懂各种类 bnf 的语法描述外。 <strong>可以利用 <code>bnf</code> 的思想来抽象编程问题。</strong></p><h2 id="bnf-的规则描述" tabindex="-1">BNF 的规则描述 <a class="header-anchor" href="#bnf-的规则描述" aria-label="Permalink to &quot;BNF 的规则描述&quot;">​</a></h2><p>BNF 利用符号来进行规则定义，相关符号的含义如下表。 这里 bnf 不仅仅指基础的巴克斯范式还包括 <a href="ftp://ftp.rfc-editor.org/in-notes/rfc4234.txt" target="_blank" rel="noreferrer">ABNF</a> 规则。</p><table tabindex="0"><thead><tr><th style="text-align:left;">符号</th><th>作用</th></tr></thead><tbody><tr><td style="text-align:left;"><code>::=</code></td><td>表示被定义为，有时也可用 <code>=</code></td></tr><tr><td style="text-align:left;">\`</td><td>\`</td></tr><tr><td style="text-align:left;"><code>/</code></td><td>表示选择</td></tr><tr><td style="text-align:left;"><code>&lt;&gt;</code></td><td>表示一个属性或类型</td></tr><tr><td style="text-align:left;"><code>；</code></td><td>结束符</td></tr><tr><td style="text-align:left;"><code></code></td><td>空格表示连接符</td></tr><tr><td style="text-align:left;"><code>[]</code></td><td>括号中内容可选</td></tr><tr><td style="text-align:left;"><code>{}</code></td><td>表示对前面内容的重复次数，其中可以填入数字，类似正则</td></tr><tr><td style="text-align:left;"><code>()</code></td><td>括号中的内容为一组</td></tr></tbody></table><h2 id="规则举例" tabindex="-1">规则举例 <a class="header-anchor" href="#规则举例" aria-label="Permalink to &quot;规则举例&quot;">​</a></h2><h3 id="用来包含规则名" tabindex="-1"><code>&lt;&gt;</code> 用来包含规则名 <a class="header-anchor" href="#用来包含规则名" aria-label="Permalink to &quot;\`&lt;&gt;\` 用来包含规则名&quot;">​</a></h3><p>范例：</p><pre><code>name =  &lt;rulename&gt; | rulename
</code></pre><p>规则名不区分大小写,也可以不带尖括号</p><h3 id="空格对多个属性进行分隔" tabindex="-1">空格对多个属性进行分隔 <a class="header-anchor" href="#空格对多个属性进行分隔" aria-label="Permalink to &quot;空格对多个属性进行分隔&quot;">​</a></h3><p>范例：</p><pre><code>foo         =  %x61           ; a
bar         =  %x62           ; b
mumble      =  foo bar foo
</code></pre><p>利用空格，分号给一个规则赋值时多个属性的方法</p><h3 id="选择" tabindex="-1">/ 选择 <a class="header-anchor" href="#选择" aria-label="Permalink to &quot;/ 选择&quot;">​</a></h3><p>范例：</p><pre><code>  foo / bar
</code></pre><p>/ 表示从这 foo 或 bar 中选择一个</p><h3 id="序列组" tabindex="-1">() 序列组 <a class="header-anchor" href="#序列组" aria-label="Permalink to &quot;() 序列组&quot;">​</a></h3><p>范例： (elem foo) / (bar blat)</p><p>括号表示一个序列组</p><h3 id="不定循环" tabindex="-1">不定循环 <a class="header-anchor" href="#不定循环" aria-label="Permalink to &quot;不定循环&quot;">​</a></h3><p>范例：</p><div class="language-md line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">&lt;a&gt;*&lt;b&gt;element  //元素 element 至少出现 a 此至多 b 次</span></span>
<span class="line"><span style="color:#E1E4E8;">*&lt;element&gt;</span><span style="color:#E1E4E8;">      //出现任意次数</span></span>
<span class="line"><span style="color:#E1E4E8;">3*3&lt;element&gt;    //只出现 3 次</span></span>
<span class="line"><span style="color:#E1E4E8;">1*&lt;element&gt;     //至少 1 次</span></span>
<span class="line"><span style="color:#E1E4E8;">1*2&lt;element&gt;    //这是1-2 次</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>默认值 <code>0 * ∞ &lt;element&gt;</code></p><h3 id="指定循环" tabindex="-1">指定循环 <a class="header-anchor" href="#指定循环" aria-label="Permalink to &quot;指定循环&quot;">​</a></h3><p>范例：</p><pre><code>&lt;n&gt;element
等同于
&lt;n&gt;*&lt;n&gt;element
</code></pre><p>相当于只使用 n 次某元素</p><h3 id="可选序列" tabindex="-1">可选序列 <a class="header-anchor" href="#可选序列" aria-label="Permalink to &quot;可选序列&quot;">​</a></h3><p>范例：</p><pre><code>[foo bar]
等同于
*1(foo bar)
</code></pre><p>表明某一规则只出现 0 或 1 次</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="http://cui.unige.ch/db-research/Enseignement/analyseinfo/AboutBNF.html#Marcotty86" target="_blank" rel="noreferrer">BNF 注释</a></p><p><a href="ftp://ftp.rfc-editor.org/in-notes/rfc4234.txt" target="_blank" rel="noreferrer">ABNF</a></p>`,40)])])}const f=t(l,[["render",o]]);export{b as __pageData,f as default};
